package com.limelight.binding.input.secondscreen;

/**
 * Sink for input generated by the second-screen trackpad / keyboard.
 * All methods are called on the main thread.
 */
public interface SecondScreenInputListener {
    void onMouseMove(short deltaX, short deltaY);

    /** @param button one of MouseButtonPacket.BUTTON_* */
    void onMouseButton(byte button, boolean down);

    /** High-res vertical scroll, 120 = one wheel notch. Positive scrolls up. */
    void onVerticalScroll(short amount);

    /** High-res horizontal scroll, 120 = one wheel notch. Positive scrolls right. */
    void onHorizontalScroll(short amount);

    /** @param androidKeyCode a KeyEvent.KEYCODE_* value */
    void onKeyboardKey(int androidKeyCode, boolean down);

    /** The back button on the second screen: leave the stream and return to the app list. */
    void onBackToAppList();
}
